#if WINDOWS

using System.Runtime.InteropServices;

namespace Altim.Platform.Windows.Interop;

/// <summary>
/// The Win32 surface Altim uses on Windows: one message-only window, one hidden
/// top-level window, the shell notification area, GDI+ for decoding the icon assets,
/// and the tool-help snapshot used to detect provider processes.
/// </summary>
/// <remarks>
/// <para>
/// Every entry point is generated by <c>LibraryImport</c> rather than <c>DllImport</c>
/// so the marshalling stubs are source generated and the assembly stays Native AOT
/// clean, and every module is resolved from <c>System32</c> so a DLL of the same name
/// beside the executable cannot be loaded instead.
/// </para>
/// <para>
/// Nothing here reads a process command line. The tool-help snapshot exposes an
/// executable name, a process id and a parent id and nothing else, which is the whole
/// reason it is used in preference to a WMI query.
/// </para>
/// </remarks>
internal static unsafe partial class NativeMethods
{
    /// <summary>Base of the private message range a window may use for itself.</summary>
    internal const uint WM_APP = 0x8000;

    /// <summary>Base of the message range the shell uses for notification icon events.</summary>
    internal const uint WM_USER = 0x0400;

    internal const uint WM_DESTROY = 0x0002;
    internal const uint WM_CLOSE = 0x0010;
    internal const uint WM_NULL = 0x0000;
    internal const uint WM_LBUTTONUP = 0x0202;
    internal const uint WM_RBUTTONUP = 0x0205;
    internal const uint WM_CONTEXTMENU = 0x007B;
    internal const uint WM_POWERBROADCAST = 0x0218;

    /// <summary>Version 4 primary activation: mouse or keyboard.</summary>
    internal const uint NIN_SELECT = WM_USER + 0;

    /// <summary>Version 4 primary activation from the keyboard.</summary>
    internal const uint NIN_KEYSELECT = WM_USER + 1;

    internal const uint NIM_ADD = 0x00000000;
    internal const uint NIM_MODIFY = 0x00000001;
    internal const uint NIM_DELETE = 0x00000002;
    internal const uint NIM_SETVERSION = 0x00000004;

    internal const uint NIF_MESSAGE = 0x00000001;
    internal const uint NIF_ICON = 0x00000002;
    internal const uint NIF_TIP = 0x00000004;
    internal const uint NIF_SHOWTIP = 0x00000080;

    /// <summary>
    /// Click messages carry screen coordinates and the icon id, and the shell shows the
    /// standard tooltip. Anything lower loses the coordinates.
    /// </summary>
    internal const uint NOTIFYICON_VERSION_4 = 4;

    internal const int S_OK = 0;

    internal const uint WS_POPUP = 0x80000000;
    internal const uint WS_EX_TOOLWINDOW = 0x00000080;
    internal const uint WS_EX_NOACTIVATE = 0x08000000;

    /// <summary>Parent handle that makes a window message-only.</summary>
    internal static readonly IntPtr HWND_MESSAGE = -3;

    internal const int GWLP_USERDATA = -21;

    internal const int SM_CXSMICON = 49;

    /// <summary>Walks to the root window of a hierarchy.</summary>
    internal const uint GA_ROOT = 2;

    internal const uint IMAGE_ICON = 1;
    internal const uint LR_LOADFROMFILE = 0x00000010;
    internal const uint LR_DEFAULTCOLOR = 0x00000000;

    /// <summary>Resource id of the stock application icon.</summary>
    internal static readonly IntPtr IDI_APPLICATION = 32512;

    internal const uint MF_STRING = 0x00000000;
    internal const uint MF_SEPARATOR = 0x00000800;
    internal const uint MF_GRAYED = 0x00000001;
    internal const uint MF_CHECKED = 0x00000008;

    internal const uint TPM_LEFTALIGN = 0x0000;
    internal const uint TPM_RIGHTBUTTON = 0x0002;
    internal const uint TPM_BOTTOMALIGN = 0x0020;
    internal const uint TPM_NONOTIFY = 0x0080;
    internal const uint TPM_RETURNCMD = 0x0100;

    internal const uint DEVICE_NOTIFY_WINDOW_HANDLE = 0x00000000;

    /// <summary>Power broadcast subtype carrying a registered power setting value.</summary>
    internal const int PBT_POWERSETTINGCHANGE = 0x8013;

    /// <summary>Power broadcast subtype for an automatic resume, including a wake timer.</summary>
    internal const int PBT_APMRESUMEAUTOMATIC = 0x0012;

    /// <summary>Power broadcast subtype for a resume where the user is present.</summary>
    internal const int PBT_APMRESUMESUSPEND = 0x0007;

    /// <summary>
    /// Console display state. On a modern standby machine this is the transition that
    /// actually marks a wake; the classic APM resume broadcasts can be absent.
    /// </summary>
    internal static readonly Guid GUID_CONSOLE_DISPLAY_STATE =
        new(0x6fe69556, 0x704a, 0x47a0, 0x8f, 0x24, 0xc2, 0x8d, 0x93, 0x6f, 0xda, 0x47);

    internal const uint TH32CS_SNAPPROCESS = 0x00000002;
    internal const uint PROCESS_QUERY_LIMITED_INFORMATION = 0x00001000;
    internal static readonly IntPtr INVALID_HANDLE_VALUE = -1;

