    internal static partial int GdipCreateHICONFromBitmap(IntPtr bitmap, IntPtr* hicon);

    [LibraryImport("gdiplus.dll")]
    internal static partial int GdipDisposeImage(IntPtr image);

    /// <summary>
    /// Stores a pointer in a window's user data slot. 32-bit Windows has no
    /// <c>SetWindowLongPtrW</c> export, so the width is chosen at run time.
    /// </summary>
    /// <param name="hWnd">The window.</param>
    /// <param name="index">The slot, for example <see cref="GWLP_USERDATA"/>.</param>
    /// <param name="value">The value to store.</param>
    internal static void SetWindowPointer(IntPtr hWnd, int index, IntPtr value)
    {
        if (IntPtr.Size == 8)
        {
            _ = SetWindowLongPtr64(hWnd, index, value);
        }
        else
        {
            _ = SetWindowLong32(hWnd, index, (int)value);
        }
    }

    /// <summary>Reads a pointer from a window's user data slot.</summary>
    /// <param name="hWnd">The window.</param>
    /// <param name="index">The slot, for example <see cref="GWLP_USERDATA"/>.</param>
    /// <returns>The stored value, or zero when nothing has been stored.</returns>
    internal static IntPtr GetWindowPointer(IntPtr hWnd, int index) =>
        IntPtr.Size == 8 ? GetWindowLongPtr64(hWnd, index) : GetWindowLong32(hWnd, index);

    /// <summary>Sign-extends the low word of a packed coordinate pair.</summary>
    /// <param name="value">The packed value.</param>
    /// <returns>The x coordinate, which is negative on a monitor left of the primary.</returns>
    internal static int LowInt16(IntPtr value) => (short)(value.ToInt64() & 0xFFFF);

    /// <summary>Sign-extends the high word of a packed coordinate pair.</summary>
    /// <param name="value">The packed value.</param>
    /// <returns>The y coordinate, which is negative on a monitor above the primary.</returns>
    internal static int HighInt16(IntPtr value) => (short)((value.ToInt64() >> 16) & 0xFFFF);
}

/// <summary>A window class registration.</summary>
[StructLayout(LayoutKind.Sequential)]
internal unsafe struct WNDCLASSEXW
{
    /// <summary>Size of this structure in bytes.</summary>
    public uint cbSize;

    /// <summary>Class style flags.</summary>
    public uint style;

    /// <summary>Pointer to the window procedure.</summary>
    public IntPtr lpfnWndProc;

    /// <summary>Extra bytes to allocate following the class structure.</summary>
    public int cbClsExtra;

    /// <summary>Extra bytes to allocate following the window instance.</summary>
    public int cbWndExtra;

    /// <summary>Module that owns the class.</summary>
    public IntPtr hInstance;

    /// <summary>Class icon.</summary>
    public IntPtr hIcon;

    /// <summary>Class cursor.</summary>
    public IntPtr hCursor;

    /// <summary>Class background brush.</summary>
    public IntPtr hbrBackground;

    /// <summary>Resource name of the class menu.</summary>
    public char* lpszMenuName;

    /// <summary>Class name.</summary>
    public char* lpszClassName;

    /// <summary>Small class icon.</summary>
    public IntPtr hIconSm;
}

/// <summary>A thread message.</summary>
[StructLayout(LayoutKind.Sequential)]
internal struct MSG
{
    /// <summary>Target window, or zero for a thread message.</summary>
    public IntPtr hwnd;

    /// <summary>Message identifier.</summary>
    public uint message;

    /// <summary>First message parameter.</summary>
    public IntPtr wParam;

    /// <summary>Second message parameter.</summary>
    public IntPtr lParam;

    /// <summary>Time the message was posted.</summary>
    public uint time;

    /// <summary>Cursor position at the time the message was posted.</summary>
    public POINT pt;
}

/// <summary>A point in physical screen pixels.</summary>
[StructLayout(LayoutKind.Sequential)]
internal struct POINT
{
    /// <summary>Horizontal coordinate.</summary>
    public int x;

    /// <summary>Vertical coordinate.</summary>
    public int y;
}

/// <summary>A rectangle in physical screen pixels, with exclusive right and bottom edges.</summary>
[StructLayout(LayoutKind.Sequential)]
internal struct RECT
{
    /// <summary>Left edge.</summary>
    public int left;

    /// <summary>Top edge.</summary>
    public int top;

    /// <summary>Right edge, exclusive.</summary>
    public int right;

    /// <summary>Bottom edge, exclusive.</summary>
    public int bottom;
}

/// <summary>
/// The notification area icon. The string buffers are declared as 16-bit integers
/// rather than <c>char</c> so the structure is unambiguously blittable and can be
/// passed by pointer with no marshalling stub at all.
/// </summary>
[StructLayout(LayoutKind.Sequential)]
internal unsafe struct NOTIFYICONDATAW
{
    /// <summary>Size of this structure in bytes.</summary>
    public uint cbSize;

    /// <summary>Window that receives the callback messages.</summary>
    public IntPtr hWnd;

    /// <summary>Icon identifier, unique within the owning window.</summary>
    public uint uID;

    /// <summary>Which of the remaining members are valid.</summary>
    public uint uFlags;

    /// <summary>Message the shell posts to <see cref="hWnd"/> for this icon.</summary>
    public uint uCallbackMessage;

    /// <summary>The icon to display.</summary>
    public IntPtr hIcon;

    /// <summary>Tooltip text, null terminated.</summary>
    public fixed ushort szTip[128];

    /// <summary>Icon state.</summary>
    public uint dwState;

    /// <summary>Which state bits are valid.</summary>
    public uint dwStateMask;

    /// <summary>Balloon body, unused by Altim.</summary>
    public fixed ushort szInfo[256];

    /// <summary>Balloon timeout, or the notify icon version for <c>NIM_SETVERSION</c>.</summary>
    public uint uVersion;

    /// <summary>Balloon title, unused by Altim.</summary>
    public fixed ushort szInfoTitle[64];

    /// <summary>Balloon flags, unused by Altim.</summary>
    public uint dwInfoFlags;

    /// <summary>Alternative icon identity, unused by Altim.</summary>
    public Guid guidItem;

    /// <summary>Balloon icon, unused by Altim.</summary>
    public IntPtr hBalloonIcon;
}

/// <summary>Identifies one notification area icon for a geometry query.</summary>
[StructLayout(LayoutKind.Sequential)]
internal struct NOTIFYICONIDENTIFIER
{
    /// <summary>Size of this structure in bytes.</summary>
    public uint cbSize;

    /// <summary>Window that owns the icon.</summary>
    public IntPtr hWnd;

    /// <summary>Icon identifier.</summary>
    public uint uID;

    /// <summary>Alternative icon identity, unused by Altim.</summary>
    public Guid guidItem;
}

/// <summary>Payload of a <c>PBT_POWERSETTINGCHANGE</c> broadcast.</summary>
[StructLayout(LayoutKind.Sequential)]
internal unsafe struct POWERBROADCAST_SETTING
{
    /// <summary>The setting that changed.</summary>
    public Guid PowerSetting;

    /// <summary>Length of <see cref="Data"/> in bytes.</summary>
    public uint DataLength;

    /// <summary>First byte of the value.</summary>
    public fixed byte Data[4];
}

/// <summary>GDI+ initialisation input. Only the version field is set.</summary>
[StructLayout(LayoutKind.Sequential)]
internal struct GdiplusStartupInput
{
    /// <summary>GDI+ version, always 1.</summary>
    public uint GdiplusVersion;

    /// <summary>Debug callback, unused.</summary>
    public IntPtr DebugEventCallback;

    /// <summary>Non-zero to suppress the GDI+ background thread.</summary>
    public int SuppressBackgroundThread;

    /// <summary>Non-zero to suppress external image codecs.</summary>
    public int SuppressExternalCodecs;
}

/// <summary>
/// One row of a tool-help process snapshot. The snapshot carries an executable name
/// and identifiers only; there is no field here that could hold a command line.
/// </summary>
[StructLayout(LayoutKind.Sequential)]
internal unsafe struct PROCESSENTRY32W
{
    /// <summary>Size of this structure in bytes.</summary>
    public uint dwSize;

    /// <summary>Unused.</summary>
    public uint cntUsage;

    /// <summary>Process identifier.</summary>
    public uint th32ProcessID;

    /// <summary>Unused.</summary>
    public UIntPtr th32DefaultHeapID;

    /// <summary>Unused.</summary>
    public uint th32ModuleID;

    /// <summary>Thread count.</summary>
    public uint cntThreads;

    /// <summary>Parent process identifier.</summary>
    public uint th32ParentProcessID;

    /// <summary>Base priority.</summary>
    public int pcPriClassBase;

    /// <summary>Unused.</summary>
    public uint dwFlags;

    /// <summary>Executable file name, with no directory component.</summary>
    public fixed ushort szExeFile[260];
}

#endif
